import { createMiddleware } from 'hono/factory';
import { eq, and } from 'drizzle-orm';
import { createAuthDb } from '../db';
import { sharedAuth, type Env } from '../lib/auth';
import { markSince } from '../lib/request-timing';
import type { AppContext } from '../lib/types';
import { AccessErrors, AuthErrors, problemJson, redactError } from '../lib/errors';
import { apiKeyFromAuthorization, checkApiKeyScopes, readApiKeyScopes } from '../lib/api-key-scopes';
import { member as memberTable } from '../auth/schema';

/**
 * Auth middleware - extracts session or API key and populates AppContext
 */
export const authMiddleware = createMiddleware<{
  Bindings: Env;
  Variables: { ctx: AppContext };
}>(async (c, next) => {
  // Better Auth is reached lazily, on first use: verified Quickback bearer
  // JWTs and scope-only passes never touch it. Plan 032 PR28: it is the
  // isolate's shared, already-initialized instance (sharedAuth) — building
  // one per request ran every plugin's init, the oauth-provider's resource
  // seed included (~150 ms of database round trips per cookie request).
  let __auth: ReturnType<typeof sharedAuth> | undefined;
  const getAuth = () => (__auth ??= sharedAuth(c.env));
  // Skip Better Auth routes — they handle their own authentication.
  // Exception (until 0.73.0): the deprecated aliases of the operator / roster
  // routes that moved to the API base (plan 031 Q7) read ctx.
  if (c.req.path.startsWith('/auth/v1/') && !(
      c.req.path === '/auth/v1/admin/list-organizations' ||
      c.req.path === '/auth/v1/admin/get-organization' ||
      c.req.path === '/auth/v1/admin/create-organization' ||
      c.req.path === '/auth/v1/admin/set-organization-member' ||
      c.req.path === '/auth/v1/admin/remove-organization-member'
    )) {
    c.set('ctx', { authenticated: false });
    return next();
  }

  // Skip CLI routes
  if (c.req.path.startsWith('/cli/')) {
    c.set('ctx', { authenticated: false });
    return next();
  }

  try {

    const hasAuthorization = Boolean(c.req.header('Authorization'));
    const hasApiKeyHeader = Boolean(c.req.header('x-api-key'));
    const cookieHeader = c.req.header('Cookie') || '';
    const hasSessionCookie = cookieHeader.split(';').some((part) => {
      const name = part.trim().split('=', 1)[0];
      return name === 'better-auth.session_token' ||
        name === '__Secure-better-auth.session_token' ||
        name === '__Host-better-auth.session_token';
    });
    const authMethodCount = Number(hasAuthorization) + Number(hasApiKeyHeader) + Number(hasSessionCookie);
    if (authMethodCount > 1) {
      c.set('ctx', { authenticated: false });
      return problemJson(c, {
        error: 'Multiple authentication methods provided',
        code: 'AUTH_METHOD_CONFLICT',
        layer: 'authentication',
        details: {
          provided: [
            ...(hasAuthorization ? ['authorization'] : []),
            ...(hasApiKeyHeader ? ['x-api-key'] : []),
            ...(hasSessionCookie ? ['cookie'] : []),
          ],
        },
        hint: 'Send exactly one of Cookie, Authorization: Bearer, or x-api-key per request.',
      }, 400);
    }

    // Check for API key: x-api-key, or a prefixed key as Authorization: Bearer (the
    // only header the MCP endpoint forwards).
    const apiKey = c.req.header('x-api-key') ?? apiKeyFromAuthorization(c.req.header('Authorization'));
    if (apiKey) {
      try {
        const keyResult = await (getAuth().api as any).verifyApiKey({
          body: { key: apiKey }
        });

        if (keyResult?.valid && keyResult.key) {
          // Parse metadata to get organizationId
          const metadata = keyResult.key.metadata
            ? (typeof keyResult.key.metadata === 'string'
                ? JSON.parse(keyResult.key.metadata)
                : keyResult.key.metadata)
            : {};

          // Scoped keys (metadata.scopes) narrow the owner's role to the
          // routes their scopes name; Access still runs on top. No scopes =
          // legacy full-role key. See src/lib/api-key-scopes.ts.
          const _keyScopes = readApiKeyScopes(metadata);
          if (_keyScopes === null) {
            c.set('ctx', { authenticated: false });
            return problemJson(c, AuthErrors.invalidToken('malformed_scopes'), 401);
          }
          if (_keyScopes) {
            const _scopeCheck = checkApiKeyScopes(_keyScopes, c.req.method, c.req.path);
            if (!_scopeCheck.allowed) {
              c.set('ctx', { authenticated: false });
              return problemJson(c, AccessErrors.keyScopeRequired(_scopeCheck.required, _keyScopes), 403);
            }
          }

          const activeOrgId = metadata.organizationId as string | undefined;

          // Look up the user's actual role in the organization
          let roles: string[] = [];
          let orgRole: string | undefined;
          let verifiedOrgId: string | undefined = activeOrgId;
          if (activeOrgId) {
            try {
              const authDb = createAuthDb(c.env.AUTH_DB);
              const [row] = await authDb
                .select({ role: memberTable.role })
                .from(memberTable)
                .where(
                  and(
                    eq(memberTable.userId, keyResult.key.referenceId),
                    eq(memberTable.organizationId, activeOrgId)
                  )
                );
              if (row?.role) {
                orgRole = row.role;
                // Expand via auth.roleHierarchy so a higher role (owner)
                // also satisfies access checks gated to lower roles
                // (admin, member). The api-key carries only the verified
                // org role; without this expansion, an owner gets denied
                // on routes that check ['admin'] or ['member'].
                const _roleHierarchy: string[] = [];
                const _roleIdx = _roleHierarchy.indexOf(row.role);
                roles = _roleIdx === -1
                  ? [row.role]
                  : _roleHierarchy.slice(0, _roleIdx + 1);
              } else {
                verifiedOrgId = undefined;
              }
            } catch (e) {
              console.error('[AUTH] Failed to look up member role:', redactError(e));
              verifiedOrgId = undefined;
            }
          }

          c.set('ctx', {
            authenticated: true,
            authMethod: 'api-key',
            userId: keyResult.key.referenceId,
            activeOrgId: verifiedOrgId,
            activeTeamId: undefined,
            roles,
            orgRole,
          });

          return next();
        } else if (keyResult?.error) {
          // Rate limit and expiry are hard failures
          // Better Auth's per-key limiter throws RATE_LIMITED.
          if (keyResult.error.code === 'RATE_LIMITED' || keyResult.error.code === 'RATE_LIMIT_EXCEEDED') {
            c.set('ctx', { authenticated: false });
            return problemJson(c, AuthErrors.rateLimited(), 429);
          }
          // Owner banned (customAPIKeyValidator) — the key is revoked.
          if (keyResult.error.code === 'USER_BANNED') {
            c.set('ctx', { authenticated: false });
            return problemJson(c, AuthErrors.invalidToken('owner_banned'), 401);
          }
          if (keyResult.error.message?.includes('expired')) {
            c.set('ctx', { authenticated: false });
            return problemJson(c, AuthErrors.expired(), 401);
          }
          // Key not found — fall through to session auth
        }
      } catch {
        // API key verification failed — fall through to session auth
      }
    }

    // Fall back to session-based auth.
    //
    // Per Better Auth's bearer plugin guidance — "intended only for APIs
    // that don't support cookies OR require Bearer tokens" — bearer is
    // an alternative to the cookie, not a supplement. Mixed transports are
    // already rejected above; the cookie-strip here is defense in depth so a
    // future refactor can't accidentally let an ambient cookie override an
    // explicit bearer. The api-key and JWT fast-paths already short-circuit
    // above; only session-token bearers reach getSession() here, and BA's
    // bearer plugin resolves the Authorization header when cookie auth misses.
    let sessionHeaders: Headers = c.req.raw.headers;
    if (c.req.header('Authorization')) {
      sessionHeaders = new Headers(c.req.raw.headers);
      sessionHeaders.delete('cookie');
    }
    const __qbSessionAt = performance.now();
    // Authorize from the session STORE, never Better Auth's signed cookie
    // cache: a deleted, banned, signed-out or revoked session must stop
    // working immediately, not up to session.cookieCache.maxAge later. The
    // cache still serves Better Auth's own GET /get-session.
    const session = await getAuth().api.getSession({ headers: sessionHeaders, query: { disableCookieCache: true } });
    markSince('auth.session', __qbSessionAt);

    if (!session) {
      c.set('ctx', { authenticated: false });
      return next();
    }

    // Extract organization and roles from session
    const activeOrg = (session.session as any).activeOrganizationId as string | undefined;
    // One member row, not getFullOrganization: that endpoint re-runs
    // getSession and loads the org, every invitation, every member and their
    // users just to find this one row — ~7 sequential statements per request.
    const __qbMemberAt = performance.now();
    const sessionMember = activeOrg
      ? (await createAuthDb(c.env.AUTH_DB)
          .select({ role: memberTable.role })
          .from(memberTable)
          .where(and(eq(memberTable.userId, session.user.id), eq(memberTable.organizationId, activeOrg)))
          .limit(1))[0]
      : undefined;
    markSince('auth.member', __qbMemberAt);
    const verifiedOrgId = sessionMember && activeOrg ? activeOrg : undefined;
    const userRole = (session.user as any).role || 'user';

    // Expand session role via auth.roleHierarchy for parity with the api-key
    // and JWT fast-paths.
    const _sessionRoleHierarchy: string[] = [];
    const _sessionRawRole = sessionMember?.role as string | undefined;
    const _sessionRoleIdx = _sessionRawRole ? _sessionRoleHierarchy.indexOf(_sessionRawRole) : -1;
    const _sessionExpandedRoles = !_sessionRawRole
      ? []
      : _sessionRoleIdx === -1 ? [_sessionRawRole] : _sessionRoleHierarchy.slice(0, _sessionRoleIdx + 1);

    c.set('ctx', {
      authenticated: true,
      authMethod: 'session',
      userId: session.user.id,
      sessionId: session.session.id,
      userRole,
      activeOrgId: verifiedOrgId,
      activeTeamId: undefined,
      roles: _sessionExpandedRoles,
      orgRole: sessionMember?.role,
      user: session.user,
    });


    return next();
  } catch (error) {
    console.error('Auth middleware error:', redactError(error));
    c.set('ctx', { authenticated: false });
    return next();
  }
});

